import json, sys, re
from collections import defaultdict, Counter
from datetime import datetime

raw = json.load(sys.stdin)
data = json.loads(raw['result'])
failed_exps = data['data']['experiments']

# Also load the killed data (inline from earlier result)
killed_json_path = "/tmp/killed_exps_inline.json"

# Parse killed experiments from the second registry call
# I'll re-parse the killed data that was returned inline
killed_raw = """PLACEHOLDER"""  # We'll handle this differently

# Let's focus on building the full analysis from both datasets
# First, build records for failed experiments
all_records = []

for eid, e in failed_exps.items():
    fr = e.get('failure_reason', '') or ''
    spec_fr = (e.get('spec', {}) or {}).get('failure_reason', '') or ''
    if not fr and spec_fr:
        fr = spec_fr
    notes = e.get('notes', '') or ''
    hyp = e.get('hypothesis', '') or ''
    spec = e.get('spec', {}) or {}

    # Extract model
    model = spec.get('model_name', '') or ''
    if not model:
        # Try to extract from hypothesis or exp_id
        for m in ['OLMo-2-7B', 'OLMo-2-1124-7B', 'Phi-4', 'Gemma-2', 'Qwen2.5-14B', 'Qwen2.5-7B', 'Qwen2.5-3B', 'Qwen2.5-1.5B', 'Qwen2.5-0.5B', 'Llama-3.2-3B', 'Llama-3.1-8B']:
            if m.lower().replace('-','').replace('.','') in (hyp + eid + notes).lower().replace('-','').replace('.',''):
                model = m
                break
        if not model:
            if '7b' in eid.lower() or '7B' in hyp:
                model = 'Qwen2.5-7B'
            elif '14b' in eid.lower() or '14B' in hyp:
                model = 'Qwen2.5-14B'
            elif '3b' in eid.lower() or '3B' in hyp:
                model = 'Qwen2.5-3B'
            elif '1.5b' in eid.lower() or '1.5B' in hyp or '15b' in eid.lower() or '15B' in eid:
                model = 'Qwen2.5-1.5B'
            elif '05b' in eid.lower() or '0.5B' in hyp or '0.5b' in eid.lower():
                model = 'Qwen2.5-0.5B'
            elif 'phi' in eid.lower() or 'phi' in hyp.lower():
                model = 'Phi-4'
            elif 'gemma' in eid.lower() or 'gemma' in hyp.lower():
                model = 'Gemma-2'
            elif 'olmo' in eid.lower() or 'olmo' in hyp.lower():
                model = 'OLMo-2-7B'
            elif 'llama' in eid.lower() or 'llama' in hyp.lower():
                model = 'Llama-3.2-3B'

    # Normalize model names
    model_map = {
        'Qwen/Qwen2.5-3B': 'Qwen2.5-3B',
        'Qwen/Qwen2.5-0.5B': 'Qwen2.5-0.5B',
        'Qwen/Qwen2.5-7B': 'Qwen2.5-7B',
        'Qwen/Qwen2.5-1.5B': 'Qwen2.5-1.5B',
        'Qwen/Qwen2.5-14B': 'Qwen2.5-14B',
        'OLMo-2-1124-7B': 'OLMo-2-7B',
    }
    model = model_map.get(model, model) or 'unknown'

    # Extract server
    server = spec.get('server', '') or ''
    if not server:
        if 'cqa1' in (eid + notes + hyp).lower():
            server = 'cqa1-21977'
        elif 'westd' in (eid + notes + hyp).lower():
            server = 'westd-29999'
        elif 'local' in (eid + notes + hyp).lower():
            server = 'local'
    server = server or 'unknown'

    # Determine phase
    eid_lower = eid.lower()
    if 'sft' in eid_lower or 'train' in eid_lower:
        phase = 'training'
    elif 'eval' in eid_lower:
        phase = 'eval'
    elif 'signal' in eid_lower:
        phase = 'signals'
    elif 'irt' in eid_lower or 'exp006' in eid_lower or 'exp_006' in eid_lower:
        phase = 'irt_fitting'
    elif 'sim' in eid_lower or 'exp004' in eid_lower or 'exp_004' in eid_lower:
        phase = 'simulation'
    elif 'data' in eid_lower or 'gen' in eid_lower:
        phase = 'data_gen'
    elif 'phase2' in eid_lower:
        phase = 'eval'
    else:
        phase = 'other'

    # Classify failure reason
    combined_text = (fr + ' ' + notes + ' ' + hyp).lower()
    if 'oom' in combined_text or 'out of memory' in combined_text or 'cuda out' in combined_text:
        reason_cat = 'OOM'
    elif 'duplicate' in combined_text or '重复' in combined_text or 'collision' in combined_text or 'conflict' in combined_text:
        reason_cat = 'GPU_conflict/duplicate'
    elif 'sigkill' in combined_text or 'exit_code=137' in combined_text or 'killed by' in combined_text:
        reason_cat = 'SIGKILL/process_killed'
    elif 'version' in combined_text or '版本' in combined_text or 'evaluate.py' in combined_text.lower() and ('old' in combined_text or 'invalidat' in combined_text or 'mismatch' in combined_text):
        reason_cat = 'version_mismatch'
    elif 'ssh' in combined_text or '断连' in combined_text or 'connection' in combined_text:
        reason_cat = 'SSH/connection'
    elif 'timeout' in combined_text or '超时' in combined_text or 'hung' in combined_text or 'unresponsive' in combined_text:
        reason_cat = 'timeout/hang'
    elif 'command not found' in combined_text or 'exit_code=127' in combined_text or 'exit_code=2' in combined_text or 'syntax' in combined_text:
        reason_cat = 'env/command_error'
    elif 'deprecated' in combined_text or 'alpha=16' in combined_text or 'lr=2e-4' in combined_text or 'confound' in combined_text or 'superseded' in combined_text:
        reason_cat = 'deprecated/superseded'
    elif 'degenerate' in combined_text or 'invalid' in combined_text:
        reason_cat = 'invalid_results'
    elif 'process dead' in combined_text or 'auto-resolved' in combined_text:
        reason_cat = 'process_died_unknown'
    elif 'director' in combined_text and ('kill' in combined_text or 'ordered' in combined_text):
        reason_cat = 'director_kill'
    elif fr.strip() == '' and notes.strip() == '':
        reason_cat = 'unknown/no_info'
    else:
        reason_cat = 'other'

    created = e.get('created_at', '')

    all_records.append({
        'exp_id': eid,
        'conclusion': 'failed',
        'model': model,
        'server': server,
        'phase': phase,
        'reason_cat': reason_cat,
        'failure_reason': fr[:200],
        'created_at': created,
    })

print(f"Total failed records: {len(all_records)}")
print("\n=== BY FAILURE REASON ===")
reason_counts = Counter(r['reason_cat'] for r in all_records)
for reason, count in reason_counts.most_common():
    print(f"  {reason}: {count}")

print("\n=== BY MODEL ===")
model_counts = Counter(r['model'] for r in all_records)
for model, count in model_counts.most_common():
    print(f"  {model}: {count}")

print("\n=== BY SERVER ===")
server_counts = Counter(r['server'] for r in all_records)
for server, count in server_counts.most_common():
    print(f"  {server}: {count}")

print("\n=== BY PHASE ===")
phase_counts = Counter(r['phase'] for r in all_records)
for phase, count in phase_counts.most_common():
    print(f"  {phase}: {count}")

print("\n=== BY TIME PERIOD ===")
for r in all_records:
    if r['created_at']:
        try:
            dt = datetime.fromisoformat(r['created_at'].replace('Z', '+00:00'))
            r['date'] = dt.strftime('%Y-%m-%d')
        except:
            r['date'] = 'unknown'
    else:
        r['date'] = 'unknown'

date_counts = Counter(r['date'] for r in all_records)
for date, count in sorted(date_counts.items()):
    print(f"  {date}: {count}")

# Dump full records for YAML generation
json.dump(all_records, open('/tmp/failed_analysis.json', 'w'), indent=2)
